draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  // draw a symbolic object: a house with a clock representing home and time, totaling 1171 days or approximately 3.2 years
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 50, 100, 100);
  ctx.stroke();
  // draw a clock
  ctx.beginPath();
  ctx.arc(W/2, H/2, 40, 0, 2 * Math.PI);
  ctx.stroke();
  // draw clock hands
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 30 * Math.sin(t), H/2 - 30 * Math.cos(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 20 * Math.sin(3 * t), H/2 - 20 * Math.cos(3 * t));
  ctx.stroke();
  // draw a number 1, 1, and 7, and a small stick figure in the house
  ctx.font = '40px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('11', W/2 - 70, H/2 - 120);
  ctx.fillText('71', W/2 - 70, H/2 - 70);
  // draw a small stick figure
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 10);
  ctx.lineTo(W/2 - 20, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2);
  ctx.lineTo(W/2 - 30, H/2 - 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2);
  ctx.lineTo(W/2 - 10, H/2 - 10);
  ctx.stroke();
  ctx.restore();
}
